ruby -rcsv -e '
path="/Users/ataulhai/Downloads/engineering-intern-take-home/export/visits.csv"
rows=CSV.read(path, headers:true)
rx=/diabet|\bt2dm\b|\bdm\b/i
forward=rows.select{|r| r["notes"].to_s.match?(rx) && r["department"] != "Diabetology"}
reverse=rows.select{|r| r["department"] == "Diabetology" && !r["notes"].to_s.match?(rx)}
puts "TOTAL=#{rows.length}"
puts "FORWARD=#{forward.length}"
forward.each{|r| puts [r["visit_id"],r["mrn"],r["visit_date"],r["department"],r["notes"]].to_csv}
puts "REVERSE=#{reverse.length}"
reverse.each{|r| puts [r["visit_id"],r["mrn"],r["visit_date"],r["department"],r["notes"]].to_csv}
'

