ruby -rcsv -rdate -e '
base="/Users/ataulhai/Downloads/engineering-intern-take-home/export"
patients=CSV.read("#{base}/patients.csv",headers:true)
labs=CSV.read("#{base}/lab_results.csv",headers:true)
rxs=CSV.read("#{base}/prescriptions.csv",headers:true)
parse=->(s){ Date.strptime(s.to_s.strip,"%d %b %y") rescue Date.parse(s.to_s.strip) }
labs_by=Hash.new{|h,k|h[k]=[]}; labs.each{|r| labs_by[r["mrn"]]<<r}
rxs_by=Hash.new{|h,k|h[k]=[]}; rxs.each{|r| rxs_by[r["mrn"]]<<r}
no=patients.select{|p| labs_by[p["mrn"]].empty?}
multiple=patients.select{|p| labs_by[p["mrn"]].length>1}
stale=patients.select{|p| l=labs_by[p["mrn"]].max_by{|r|parse.call(r["collected_on"])}; q=rxs_by[p["mrn"]].max_by{|r|Date.parse(r["prescribed_on"])}; l && q && parse.call(l["collected_on"]) < Date.parse(q["prescribed_on"])}
puts "patients=#{patients.length} labs=#{labs.length} prescriptions=#{rxs.length}"
puts "no_labs=#{no.length} multiple_labs=#{multiple.length} stale_vs_latest_rx=#{stale.length}"
puts "with_rx=#{patients.count{|p|!rxs_by[p["mrn"]].empty?}}"
puts "no_labs_with_rx=#{no.count{|p|!rxs_by[p["mrn"]].empty?}}"
puts "multiple_distribution=#{patients.group_by{|p|labs_by[p["mrn"]].length}.sort.map{|k,v|"#{k}:#{v.length}"}.join(", ")}"
puts "overlap_no_multiple=#{no.count{|p|labs_by[p["mrn"]].length>1}} overlap_stale_multiple=#{stale.count{|p|labs_by[p["mrn"]].length>1}}"
'

